                valveDRun := FALSE;
                mixMotorRun := FALSE;
            STATE_MIXING:
                valveARun := FALSE;
                valveBRun := FALSE;
                valveCRun := FALSE;
                valveDRun := FALSE;
                mixMotorRun := TRUE;
            STATE_DONE:
                valveARun := FALSE;
                valveBRun := FALSE;
                valveCRun := FALSE;
                valveDRun := TRUE;
                mixMotorRun := FALSE;
        END_CASE;
    END_IF;
END_IF;

