TYPE T_PRODUCTION_STATE :
(
    IDLE,
    MOVING_FEED_TO_WASH,
    AT_WASH,
    MOVING_WASH_TO_WEIGHT,
    AT_WEIGHT_WAIT,
    AT_WEIGHT_REJECT,
    MOVING_WEIGHT_TO_FIRING,
    AT_FIRING,
    MOVING_FIRING_TO_OUTPUT,
    AT_OUTPUT
);
END_TYPE;

FUNCTION_BLOCK ProductionControl
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorFeed : BOOL;
    SensorWash : BOOL;
    SensorWeight : BOOL;
    SensorFiring : BOOL;
    SensorOutput : BOOL;
    washComplete : BOOL;
    weightComplete : BOOL;
    weight : REAL;
    firingComplete : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL;
    MotorReverse : BOOL;
    kick : BOOL;
    CompletionLight : BOOL;
    firingTemp : REAL;
END_VAR
VAR
    currentState : T_PRODUCTION_STATE := IDLE;
END_VAR

IF Mode = FALSE THEN
    // Manual mode
    IF ForwardButton AND NOT ReverseButton THEN
        MotorForward := TRUE;
        MotorReverse := FALSE;
    ELSIF ReverseButton AND NOT ForwardButton THEN
        MotorForward := FALSE;
        MotorReverse := TRUE;
    ELSE
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF;
    // Reset all automatic outputs and state
    kick := FALSE;
    CompletionLight := FALSE;
    firingTemp := 0.0;
    currentState := IDLE;
ELSE
    // Automatic mode
    // Set default outputs for this scan
    MotorReverse := FALSE;
    MotorForward := FALSE;
    kick := FALSE;
    CompletionLight := FALSE;
    // firingTemp retains its last calculated value unless updated in qualified weighing

    CASE currentState OF
        IDLE:
            IF SensorFeed THEN
                currentState := MOVING_FEED_TO_WASH;
                MotorForward := TRUE;
            END_IF;

        MOVING_FEED_TO_WASH:
            MotorForward := TRUE;
            IF SensorWash THEN
                MotorForward := FALSE;
                currentState := AT_WASH;
            END_IF;

        AT_WASH:
            IF washComplete THEN
                MotorForward := TRUE;
                currentState := MOVING_WASH_TO_WEIGHT;
            END_IF;

        MOVING_WASH_TO_WEIGHT:
            MotorForward := TRUE;
            IF SensorWeight THEN
