    ButtonA : BOOL;
    ButtonB : BOOL;
    ButtonC : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL;
    MotorReverse : BOOL;
    CompletionLight : BOOL;
END_VAR
VAR
    State : AutoState := IDLE;
    CompletionLatched : BOOL := FALSE;
END_VAR

MotorForward := FALSE;
MotorReverse := FALSE;
CompletionLight := FALSE;

IF NOT Mode THEN
    State := IDLE;
