    IF ForwardButton AND NOT ReverseButton THEN
        MotorForward := TRUE;
    ELSIF ReverseButton AND NOT ForwardButton THEN
        MotorReverse := TRUE;
    END_IF;
ELSE
    CASE State OF
        IDLE:
            IF SensorA AND ButtonA THEN
                State := MOVING_TO_B;
            ELSIF SensorB THEN
                State := WAIT_B;
            ELSIF SensorC THEN
                State := WAIT_C;
            END_IF;

        MOVING_TO_B:
