        END_FOR;
        newArr[prevCount + 1] := pushItem;
    ELSE
        FOR i := 1 TO prevCount DO
            newArr[i] := oldF[i];
        END_FOR;
    END_IF;
END_IF;

FOR i := 1 TO 8 DO
    fifo[i] := newArr[i];
END_FOR;

IF newCount > 0 THEN
    head := newArr[1];
ELSE
    head := 0;
END_IF;

count := newCount;
full := (newCount = 8);
empty := (newCount = 0);

prevPush := pushEn;
prevPop := popEn;
prevCount := newCount;
END_FUNCTION_BLOCK

