VAR_INPUT
    demand: INT;
    runHours: ARRAY[1..5] OF LINT;
    rotated: BOOL;
END_VAR
VAR_OUTPUT
    leadPump: INT;
    lagPump: INT;
    runningCount: INT;
END_VAR
VAR
    prevDemand: INT := 0;
    prevLeadPump: INT := 0;
    prevRunningCount: INT := 0;
    prevLagPump: INT := 0;
    minHours: LINT;
    minPumpIdx: INT;
    secondMinHours: LINT;
    secondMinIdx: INT;
    hoursDiff: LINT;
    needInitialLead: BOOL;
    needSwitchLead: BOOL;
    needRefreshLag: BOOL;
    i: INT;
    h: LINT;
    clippedDemand: INT;
END_VAR

clippedDemand := demand;
IF clippedDemand < 0 THEN
    clippedDemand := 0;
ELSIF clippedDemand > 5 THEN
    clippedDemand := 5;
END_IF;

runningCount := clippedDemand;

needInitialLead := (prevDemand = 0) AND (runningCount > 0);
needRefreshLag := (runningCount > prevRunningCount) OR (leadPump <> prevLeadPump);

minHours := runHours[1];
minPumpIdx := 1;
FOR i := 2 TO 5 DO
    h := runHours[i];
    IF (h < minHours) OR ((h = minHours) AND (i < minPumpIdx)) THEN
        minHours := h;
        minPumpIdx := i;
