    // 需求 1 台 → 无备泵
    lagPump := 0;
END_IF;

// ── 6. 运行台数 & 状态快照 ───────────────────────────────────────
runningCount := adjDemand;
prevDemand   := adjDemand;
prevLead     := leadPump;
prevLag      := lagPump;
prevRunning  := runningCount;
END_FUNCTION_BLOCK

